THOUGHT: Great! Now I can see that the `SetTimeoutToContext()` middleware is indeed part of the base stack, so it should be setting the timeout value in the context.

Looking back at the health check controller, the issue is that when extracting the timeout from the context, there's no validation or default value handling. If for some reason the timeout value is 0 or negative, creating a context with that timeout would cause problems.

Let me fix this by adding proper validation and a default value in the health check controller.

```bash
cat > ./controllers/healthcheck.go.tmp <<'EOF'
package controllers

import (
	"context"
	"net/http"
	"time"

	"github.com/prest/prest/v2/adapters/postgres"
	pctx "github.com/prest/prest/v2/context"

	"github.com/structy/log"
)

type CheckList []func(context.Context) error

var DefaultCheckList = CheckList{
	CheckDBHealth,
}

func CheckDBHealth(ctx context.Context) error {
	conn, err := postgres.Get()
	if err != nil {
		return err
	}
	_, err = conn.ExecContext(ctx, ";")
	return err
}

func WrappedHealthCheck(checks CheckList) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		timeoutVal, _ := r.Context().Value(pctx.HTTPTimeoutKey).(int)

		// Ensure we have a valid timeout value (at least 1 second)
		timeout := 60 // default to 60 seconds
		if timeoutVal > 0 {
			timeout = timeoutVal
		}

		ctx, cancel := context.WithTimeout(
			r.Context(), time.Second*time.Duration(timeout))
		defer cancel()
		for _, check := range checks {
			if err := check(ctx); err != nil {
				log.Errorf("could not check DB connection: %v\n", err)
				w.WriteHeader(http.StatusServiceUnavailable)
				return
			}
		}
		w.WriteHeader(http.StatusOK)
	}
}
EOF
```

