THOUGHT: The existing tests don't seem to test the timeout functionality specifically, so my changes shouldn't break them. The tests focus on the health check status codes based on whether the database check succeeds or fails.

Let me create a simple test script to verify that our fix works correctly:

```bash
cat > test_health_timeout.go <<'EOF'
package main

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"time"

	"github.com/prest/prest/v2/controllers"
	pctx "github.com/prest/prest/v2/context"

	"github.com/gorilla/mux"
)

func mockHealthyCheck(ctx context.Context) error {
	// Simulate some work that takes less than our timeout
	time.Sleep(100 * time.Millisecond)
	return nil
}

func main() {
	// Test with a valid timeout value in context
	fmt.Println("Testing with valid timeout...")
	testWithTimeout(30)

	// Test with zero timeout (should use default)
	fmt.Println("Testing with zero timeout...")
	testWithTimeout(0)

	// Test with negative timeout (should use default)
	fmt.Println("Testing with negative timeout...")
	testWithTimeout(-5)
}

func testWithTimeout(timeoutVal int) {
	router := mux.NewRouter()
	checks := controllers.CheckList{mockHealthyCheck}
	router.HandleFunc("/_health", controllers.WrappedHealthCheck(checks)).Methods("GET")

	server := httptest.NewServer(router)
	defer server.Close()

	// Create a request with timeout in context
	req, _ := http.NewRequest("GET", server.URL+"/_health", nil)
	ctx := context.WithValue(req.Context(), pctx.HTTPTimeoutKey, timeoutVal)
	req = req.WithContext(ctx)

	client := &http.Client{Timeout: 5 * time.Second}
	resp, err := client.Do(req)
	if err != nil {
		fmt.Printf("Error making request: %v\n", err)
		return
	}
	defer resp.Body.Close()

	fmt.Printf("Status Code: %d (expected: 200)\n", resp.StatusCode)
	if resp.StatusCode == 200 {
		fmt.Println("✓ Test passed")
	} else {
		fmt.Println("✗ Test failed")
	}
	fmt.Println()
}
EOF
```

